from abc import ABC, abstractmethod
from typing import Dict, Any, Optional, List, Tuple
from pyrogram.types import Message


class IMediaRepository(ABC):
    """Abstract interface for media database operations."""

    @abstractmethod
    async def save_file(self, media: Message):
        """Save a media file."""
        pass

    @abstractmethod
    async def get_search_results(
        self, query: str, file_type=None, max_results=10, offset=0, filter=False
    ):
        """Fetch search results."""
        pass

    @abstractmethod
    async def get_file_details(self, file_id: str):
        """Fetch file details."""
        pass


class IUserRepository(ABC):
    """Abstract interface for user database operations."""

    @abstractmethod
    async def is_user_exist(self, user_id: int) -> bool:
        pass

    @abstractmethod
    async def add_user(self, user_id: int, name: str):
        pass

    @abstractmethod
    async def total_users_count(self) -> int:
        pass

    @abstractmethod
    async def ban_user(self, user_id: int, ban_reason: str):
        pass

    @abstractmethod
    async def remove_ban(self, user_id: int):
        pass

    @abstractmethod
    async def get_ban_status(self, user_id: int) -> Dict[str, Any]:
        pass

    @abstractmethod
    async def get_all_users(self):
        pass

    @abstractmethod
    async def delete_user(self, user_id: int):
        pass

    @abstractmethod
    async def get_banned(self) -> Tuple[List[int], List[int]]:
        """Return banned users and chats."""
        pass


class IGroupRepository(ABC):
    """Abstract interface for group/chat database operations."""

    @abstractmethod
    async def add_chat(self, chat_id: int, title: str):
        pass

    @abstractmethod
    async def get_chat(self, chat_id: int) -> Optional[Dict[str, Any]]:
        pass

    @abstractmethod
    async def disable_chat(self, chat_id: int, reason: str):
        pass

    @abstractmethod
    async def re_enable_chat(self, chat_id: int):
        pass

    @abstractmethod
    async def get_settings(self, chat_id: int) -> Dict[str, Any]:
        pass

    @abstractmethod
    async def update_settings(self, chat_id: int, settings: Dict[str, Any]):
        pass

    @abstractmethod
    async def total_chat_count(self) -> int:
        pass

    @abstractmethod
    async def get_all_chats(self):
        pass
